-- 하나를 만들어 둘에 쓴다

private BooleanBuilder buildCondition(MemberSearchCondition cond) {
    BooleanBuilder builder = new BooleanBuilder();
    if (hasText(cond.getUsername()))
        builder.and(member.username.eq(cond.getUsername()));
    if (hasText(cond.getTeamName()))
        builder.and(team.name.eq(cond.getTeamName()));
    if (cond.getAgeGoe() != null)
        builder.and(member.age.goe(cond.getAgeGoe()));
    if (cond.getAgeLoe() != null)
        builder.and(member.age.loe(cond.getAgeLoe()));
    return builder;
}

@Test
void 같은_조건() {
    em.clear();
    MemberSearchCondition cond = new MemberSearchCondition();
    cond.setUsername("m1");
    cond.setAgeGoe(20);

    BooleanBuilder builder = buildCondition(cond);

    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(member.id, member.username,
                    member.age, team.id, team.name))
            .from(member).leftJoin(member.team, team)
            .where(builder).fetch();

    Long total = queryFactory.select(member.count())
            .from(member).leftJoin(member.team, team)
            .where(builder).fetchOne();

    System.out.println("목록 " + content.size() + " / 전체 " + total);
}

